import { ServiceType } from '@bufbuild/protobuf';
import { PromiseClient, Transport, createPromiseClient } from '@connectrpc/connect';
import { createGrpcTransport } from '@connectrpc/connect-node';
import CoreClient, { headers } from './core';

export default class GrpcConnect {
  private transport: Transport;
  constructor(
    private readonly coreClient: CoreClient
  ) {
    this.transport = createGrpcTransport({
      baseUrl: this.coreClient.envUrl,
      httpVersion: "2",
      interceptors: [
        (next) => {
          return (req) => {
            req.header.set(headers['user-agent'], this.coreClient.userAgent)
            req.header.set(headers['x-sdk-version'], this.coreClient.sdkVersion)
            req.header.set(headers['x-api-version'], this.coreClient.apiVersion)
            if (this.coreClient.accessToken) {
              req.header.set(headers.authorization, `Bearer ${this.coreClient.accessToken}`)
            }
            return next(req)
          }
        }
      ],
    });
  }

  createClient<T extends ServiceType>(service: T): PromiseClient<T> {
    return createPromiseClient(service, this.transport);
  }
}

import { PromiseClient } from '@connectrpc/connect';
import GrpcConnect from './connect';
import CoreClient from './core';
import { ConnectionService } from './pkg/grpc/scalekit/v1/connections/connections_connect';
import { GetConnectionResponse, ToggleConnectionResponse, ListConnectionsResponse } from './pkg/grpc/scalekit/v1/connections/connections_pb';

export default class ConnectionClient {
  private client: PromiseClient<typeof ConnectionService>;
  constructor(
    private readonly grpcConncet: GrpcConnect,
    private readonly coreClient: CoreClient
  ) {
    this.client = this.grpcConncet.createClient(ConnectionService);
  }

  /**
   * Get a connection by id and organization id
   * @param organizationId The organization id
   * @param id The connection id
   * @returns {Promise<GetConnectionResponse>} The connection
   */
  async getConnection(organizationId: string, id: string): Promise<GetConnectionResponse> {
    return this.coreClient.connectExec(
      this.client.getConnection,
      {
        id,
        organizationId
      },
    )
  }

  /**
   * List connections by domain
   * @param domain The domain
   * @returns {Promise<ListConnectionsResponse>} The connection
   */
  async listConnectionsByDomain(domain: string): Promise<ListConnectionsResponse> {
    return this.coreClient.connectExec(
      this.client.listConnections,
      {
        domain
      },
    )
  }

  /**
   * List connections by organization id
   * @param organizationId The organization id
   * @returns {Promise<ListConnectionsResponse>} The list of connections
   */
  async listConnections(organizationId: string): Promise<ListConnectionsResponse> {
    return this.coreClient.connectExec(
      this.client.listConnections,
      {
        organizationId
      },
    )
  }

  /**
   * Enable a connection by id and organization id
   * @param organizationId The organization id
   * @param id The connection id
   * @returns {Promise<ToggleConnectionResponse>} The connection enable response
   */
  async enableConnection(organizationId: string, id: string): Promise<ToggleConnectionResponse> {
    return this.coreClient.connectExec(
      this.client.enableConnection,
      {
        id,
        organizationId
      },
    )
  }

  /**
   * Disable a connection by id and organization id
   * @param organizationId The organization id
   * @param id The connection id
   * @returns {Promise<ToggleConnectionResponse>} The connection enable response
   */
  async disableConnection(organizationId: string, id: string): Promise<ToggleConnectionResponse> {
    return this.coreClient.connectExec(
      this.client.disableConnection,
      {
        id,
        organizationId
      },
    )
  }
}

import { Empty, PartialMessage } from '@bufbuild/protobuf';
import { PromiseClient } from '@connectrpc/connect';
import GrpcConnect from './connect';
import CoreClient from './core';
import { OrganizationService } from './pkg/grpc/scalekit/v1/organizations/organizations_connect';
import { CreateOrganizationResponse, GetOrganizationResponse, Link, ListOrganizationsResponse, UpdateOrganization, UpdateOrganizationResponse } from './pkg/grpc/scalekit/v1/organizations/organizations_pb';
import { OrganizationSettings } from './types/organization';
export default class OrganizationClient {
  private client: PromiseClient<typeof OrganizationService>;
  constructor(
    private readonly grpcConncet: GrpcConnect,
    private readonly coreClient: CoreClient
  ) {
    this.client = this.grpcConncet.createClient(OrganizationService);
  }

  /** 
  * Create an organization with the given name. Optionally, you can provide an external id.
  * @param {string} name The organization name
  * @param {object} options The options to create an organization
  * @param {string} options.externalId The external id
  * @returns {Promise<CreateOrganizationResponse>} The created organization
  */
  async createOrganization(name: string, options?: { externalId?: string }): Promise<CreateOrganizationResponse> {
    return this.coreClient.connectExec(
      this.client.createOrganization,
      {
        organization: {
          displayName: name,
          ...(options?.externalId && {
            externalId: options.externalId
          })
        }
      }
    )
  }

  /**
   * List organizations with pagination
   * @param {object} options The options to list organizations
   * @param {number} options.pageSize The page size
   * @param {string} options.pageToken The page token
   * @returns {Promise<ListOrganizationResponse>} The list of organizations
   */
  async listOrganization(options?: {
    pageSize?: number,
    pageToken?: string
  }): Promise<ListOrganizationsResponse> {
    return this.coreClient.connectExec(
      this.client.listOrganization,
      options ? options : {},
    )
  }

  /**
   * Get an organization by id
   * @param {string} id The organization id
   * @returns {Promise<GetOrganizationResponse>} The organization
   */
  async getOrganization(id: string): Promise<GetOrganizationResponse> {
    return this.coreClient.connectExec(
      this.client.getOrganization,
      { identities: { case: 'id', value: id } },
    )
  }

  /**
   * Get an organization by external id
   * @param {string} externalId The external id
